154	    /** A dated setting's value in force on the date: the one with the latest from-date on or before it; "" when there is none. */
155	    public String on(String sheetId, String key, LocalDate date) {
156	        List<String> values = jdbc.queryForList("SELECT setting_value FROM " + AsOf.table("setting_from") + " WHERE sheet_id = ? AND setting_key = ?"
157	                + " AND from_date <= ? ORDER BY from_date DESC LIMIT 1", String.class, sheetId, key, java.sql.Date.valueOf(date));
158	        return values.isEmpty() ? "" : values.get(0);
159	    }
160	
161	    /** A dated setting's values, by from-date. */
162	    public List<DatedValue> history(String sheetId, String key) {
163	        return jdbc.query("SELECT from_date, setting_value FROM " + AsOf.table("setting_from") + " WHERE sheet_id = ? AND setting_key = ? ORDER BY from_date",
164	                (rs, n) -> new DatedValue(rs.getDate("from_date").toLocalDate().toString(), rs.getString("setting_value")),
165	                sheetId, key);
166	    }
167	
168	    /** A dated setting's value from a from-date (yyyy-MM-dd). */
169	    public record DatedValue(String from, String value) {
170	    }
