177	    /** The clerk limit in force on the sheet's today; null when there is none. */
178	    public BigDecimal clerkLimit(String sheetId) {
179	        String value = current(sheetId, CLERK_LIMIT);
180	        return value.isEmpty() ? null : new BigDecimal(value);
181	    }
182	
183	    /** The key a grade's own clerk limit is kept under: clerk-limit-<grade>. */
184	    public static String gradeClerkLimitKey(String grade) {
185	        return CLERK_LIMIT + "-" + grade;
186	    }
187	
188	    /** The clerk limit in force for the claim: its person's grade's own on the sheet's today when one is set (blank is none), else the sheet's; null when there is none. */
189	    public BigDecimal clerkLimit(Claim claim) {
190	        Person person = people.find(claim.sheetId(), claim.personId());
191	        LocalDate today = sheets.today(claim.sheetId());
192	        String grade = person == null ? null : person.gradeOn(today);
193	        String value = grade == null ? "" : on(claim.sheetId(), gradeClerkLimitKey(grade), today);
194	        return value.isEmpty() ? clerkLimit(claim.sheetId()) : new BigDecimal(value);
195	    }
196	
197	    /** The cap in force on the sheet's today, with two decimals: what a person's due-total is at most; null when there is none. */
198	    public BigDecimal cap(String sheetId) {
199	        String value = current(sheetId, CAP);
200	        return value.isEmpty() ? null : new BigDecimal(value);
201	    }
202	
203	    /** The proof threshold in force on the date: a claim dated then whose due is above it is settled only with a proof; null when there is none. */
204	    public BigDecimal proofThreshold(String sheetId, LocalDate date) {
205	        String value = on(sheetId, PROOF_THRESHOLD, date);
206	        return value.isEmpty() ? null : new BigDecimal(value);
207	    }
208	
209	    /** The key a grade's own proof threshold is kept under: proof-threshold-<grade>. */
210	    public static String gradeProofKey(String grade) {
211	        return PROOF_THRESHOLD + "-" + grade;
212	    }
