214	    /** The proof threshold of the grade in force on the date: its own when one is in force (blank is none), else the sheet's; null when there is none. */
215	    public BigDecimal proofThreshold(String sheetId, String grade, LocalDate date) {
216	        String value = grade == null ? "" : on(sheetId, gradeProofKey(grade), date);
217	        return value.isEmpty() ? proofThreshold(sheetId, date) : new BigDecimal(value);
218	    }
219	
220	    /** The proof threshold in force for the claim: that of the grade its person had on its date (see {@link #proofThreshold(String, String, LocalDate)}). */
221	    public BigDecimal proofThreshold(Claim claim) {
222	        Person person = people.find(claim.sheetId(), claim.personId());
223	        return proofThreshold(claim.sheetId(), person == null ? null : person.gradeOn(claim.date()), claim.date());
224	    }
225	
226	    /** The note threshold in force on the date: a claim dated then whose due is above it is opened only with a note; null when there is none. */
227	    public BigDecimal noteThreshold(String sheetId, LocalDate date) {
228	        String value = on(sheetId, NOTE_THRESHOLD, date);
229	        return value.isEmpty() ? null : new BigDecimal(value);
230	    }
231	
232	    /** The review threshold in force on the date: a claim dated then whose due is above it goes to REVIEW when opened; null when there is none. */
233	    public BigDecimal reviewThreshold(String sheetId, LocalDate date) {
234	        String value = on(sheetId, REVIEW_THRESHOLD, date);
235	        return value.isEmpty() ? null : new BigDecimal(value);
236	    }
237	
238	    /** A person's due-total held to the sheet's cap less their cut total, not below 0.00; null (n/a) stays null. */
239	    public BigDecimal capped(String sheetId, BigDecimal dueTotal, BigDecimal cutTotal) {
240	        BigDecimal cap = cap(sheetId);
241	        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap.subtract(cutTotal).max(BigDecimal.ZERO.setScale(2)));
242	    }
243	
244	    /** The floor in force on the date, with two decimals: what a claim's live due is at least; 1.00 when none is. */
245	    public BigDecimal floor(String sheetId, LocalDate date) {
246	        String value = on(sheetId, FLOOR, date);
247	        return new BigDecimal(value.isEmpty() ? FLOOR_DEFAULT : value);
248	    }
249	
250	    /** The terms in force on the date: the number of days after its date a claim is due by; 14 when none are. */
251	    public int terms(String sheetId, LocalDate date) {
252	        String value = on(sheetId, TERMS, date);
253	        return Integer.parseInt(value.isEmpty() ? TERMS_DEFAULT : value);
254	    }
255	
256	    /**
257	     * The terms a claim made now is fixed with: those in force on the sheet's today, for a person not on the sheet the
258	     * terms of {@code grade} (the sheet's when null).
259	     */
260	    public int termsNow(String sheetId, String grade) {
261	        LocalDate today = sheets.today(sheetId);
262	        return grade == null ? terms(sheetId, today) : terms(sheetId, grade, today);
263	    }
264	
265	    /** The sheet's today. */
266	    public LocalDate today(String sheetId) {
267	        return sheets.today(sheetId);
268	    }
269	
270	    /** The key a grade's own terms are kept under: terms-<grade>. */
271	    public static String gradeTermsKey(String grade) {
272	        return TERMS + "-" + grade;
273	    }
274	
275	    /** The terms of the grade in force on the date: its own terms, or the sheet's terms when it has none of its own. */
276	    public int terms(String sheetId, String grade, LocalDate date) {
277	        String value = on(sheetId, gradeTermsKey(grade), date);
278	        return value.isEmpty() ? terms(sheetId, date) : Integer.parseInt(value);
279	    }
280	
281	    /** The key a grade's grace days are kept under: grace-<grade>. */
282	    public static String gradeGraceKey(String grade) {
283	        return "grace-" + grade;
284	    }
285	
286	    /** The grace days of the grade in force on the date: days past a claim's due-by before it is overdue; 0 when none are (blank is none). */
287	    public int grace(String sheetId, String grade, LocalDate date) {
288	        String value = grade == null ? "" : on(sheetId, gradeGraceKey(grade), date);
289	        return value.isEmpty() ? 0 : Integer.parseInt(value);
290	    }
291	
292	    /**
293	     * The date the claim's overdue count runs from: its due-by plus the grace days, in force on its date, of the grade its person
294	     * had on its date. It is overdue once this is before the sheet's today, and its late charge's 30-day boundaries count from it.
295	     */
296	    public LocalDate overdueFrom(Claim claim) {
297	        Person person = people.find(claim.sheetId(), claim.personId());
298	        String grade = person == null ? null : person.gradeOn(claim.date());
299	        return claim.dueBy().plusDays(grace(claim.sheetId(), grade, claim.date()));
300	    }
301	
302	    /** Whether the claim is overdue on {@code today}: open (OPEN or PENDING), not deferred, and its {@link #overdueFrom} is before it. */
303	    public boolean overdue(Claim claim, LocalDate today) {
304	        return claim.status().isOpen() && !claim.deferredOn(today) && claim.dueBy() != null && today != null
305	                && overdueFrom(claim).isBefore(today);
306	    }
307	
308	    /** The late percent in force on the date, with two decimals: what an overdue claim gains per full 30 days; 0.00 when none is. */
309	    public BigDecimal latePct(String sheetId, LocalDate date) {
310	        String value = on(sheetId, LATE_PCT, date);
311	        return new BigDecimal(value.isEmpty() ? LATE_PCT_DEFAULT : value);
312	    }
313	
314	    /** The policy date: the one set, or the sheet's today when it is blank. */
315	    public LocalDate policyDate(String sheetId) {
316	        String value = get(sheetId, POLICY_DATE);
317	        return value.isEmpty() ? sheets.today(sheetId) : LocalDate.parse(value);
318	    }
319	
320	    /** The date from which opened claims are numbered within their period; null when it is off. */
321	    public LocalDate periodNumberingFrom(String sheetId) {
322	        String value = get(sheetId, PERIOD_NUMBERING_FROM);
323	        return value.isEmpty() ? null : LocalDate.parse(value);
324	    }
325	
326	    /** The date a new claim left undated is given: the entry date when one is set, else the sheet's today. */
327	    public LocalDate entryDate(String sheetId) {
328	        String value = get(sheetId, ENTRY_DATE);
329	        return value.isEmpty() ? sheets.today(sheetId) : LocalDate.parse(value);
330	    }
331	
332	    /** The month (1 to 12) the sheet's fiscal year starts on. */
333	    public int fiscalStartMonth(String sheetId) {
334	        String value = get(sheetId, FISCAL_START_MONTH);
335	        return Integer.parseInt(value.isEmpty() ? FISCAL_START_MONTH_DEFAULT : value);
336	    }
337	
338	    /** The grace days: how many days after its to-date an open period is closed when the sheet's today is changed; null when it is off. */
339	    public Integer graceDays(String sheetId) {
340	        String value = get(sheetId, GRACE_DAYS);
341	        return value.isEmpty() ? null : Integer.valueOf(value);
342	    }
343	
344	    /** The pot, with two decimals; null when there is none. */
345	    public BigDecimal pot(String sheetId) {
346	        String value = get(sheetId, POT);
347	        return value.isEmpty() ? null : new BigDecimal(value).setScale(2);
348	    }
349	
350	    /** The escalation gap: how many days a claim's previous reminder must be before the sheet's today for reminding it to escalate it; null when it is off. */
351	    public Integer escalateAfter(String sheetId) {
352	        String value = get(sheetId, ESCALATE_AFTER);
353	        return value.isEmpty() ? null : Integer.valueOf(value);
354	    }
355	
356	    /** The proof kinds a claim above the proof threshold needs at least one proof of each of; empty when none are set. */
357	    /** The sheet's default grade: the one set, else A. */
358	    public String defaultGrade(String sheetId) {
359	        String value = get(sheetId, DEFAULT_GRADE);
360	        return value.isEmpty() ? "A" : value;
361	    }
362	
363	    public List<String> proofKinds(String sheetId) {
364	        String value = get(sheetId, PROOF_KINDS);
365	        return value.isEmpty() ? List.of() : List.of(value.split(","));
366	    }
367	
368	    /** The review SLA, in days; null when there is none. */
369	    public Integer reviewSla(String sheetId) {
370	        String value = get(sheetId, REVIEW_SLA);
371	        return value.isEmpty() ? null : Integer.valueOf(value);
372	    }
373	
374	    /** The maximum of OPEN or PENDING claims a person may have; null when there is none. */
375	    public Integer maxOpen(String sheetId) {
376	        String value = get(sheetId, MAX_OPEN);
377	        return value.isEmpty() ? null : Integer.valueOf(value);
378	    }
379	
380	    /** Whether the score log is on. */
381	    public boolean scoreLog(String sheetId) {
382	        return "on".equals(get(sheetId, SCORE_LOG));
383	    }
384	
385	    /** The alert threshold, with two decimals; null when alerts are off. */
386	    public BigDecimal alertThreshold(String sheetId) {
387	        String value = get(sheetId, ALERT_THRESHOLD);
388	        return value.isEmpty() ? null : new BigDecimal(value).setScale(2);
389	    }
390	
391	    /**
392	     * How the claim's live figures round: by the rounding mode in force on its date when there is one, else half up when it is
393	     * dated before the policy date, half to even on or after it. A correction rounds by the date of the claim it corrects.
394	     */
395	    public RoundingMode rounding(Claim claim) {
396	        LocalDate date = claim.date();
397	        if (claim.isCorrection() && claim.corrects() != null) {
398	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
399	            if (corrected != null) {
400	                date = corrected.date();
401	            }
402	        }
403	        String mode = on(claim.sheetId(), ROUNDING, date);
404	        if (!mode.isEmpty()) {
405	            return mode.equals("half-up") ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
406	        }
407	        return date.isBefore(policyDate(claim.sheetId())) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
408	    }
409	
410	    /** The claim's rate figure at the rate (a percent): its amount times the rate, rounded by {@link #rounding}, not yet floored; null (no rate) stays null. */
411	    public BigDecimal live(Claim claim, BigDecimal rate) {
412	        return rate == null ? null : claim.amount().multiply(rate).movePointLeft(2).setScale(2, rounding(claim));
413	    }
414	
415	    /**
416	     * A claim's live due from its rate figure: the figure raised to the floor in force on the claim's date ({@link #floored}), then its
417	     * late charge, worked out on that floored figure, added on top. An open (OPEN or PENDING) claim whose due-by (fixed when it was made) plus
418	     * its grade's grace ({@link #overdueFrom}) is before {@code today} gains, for every full 30 days it is overdue, the late percent in force on
419	     * that boundary date (the due-by plus the grace plus 30, 60, 90 ... days)
420	     * of the figure plus the charges of the boundaries before it (compounding), each charge rounded by {@link #rounding}, the charges added up; a boundary whose percent is 0.00 adds nothing.
421	     * The charge follows the sheet's today; a statement binds the due this works out (callers use the bound due as it is); null (no figure) stays null.
422	     * A correction has no late charge and no floor, and a deferred claim no late charge (it is not overdue until the sheet's today reaches its date).
423	     * A waived claim has no late charge, whatever its overdue state.
424	     */
425	    public BigDecimal withLate(Claim claim, BigDecimal figure, LocalDate today) {
426	        return lateAdded(claim, floored(claim, figure), today);
427	    }
428	
429	    /** The (floored) figure with the claim's late charge on {@code today} added on top (see {@link #withLate}). */
430	    private BigDecimal lateAdded(Claim claim, BigDecimal figure, LocalDate today) {
431	        if (figure == null || !claim.status().isOpen() || claim.isCorrection() || claim.deferredOn(today) || claim.waived()) {
432	            return figure;
433	        }
434	        LocalDate dueBy = overdueFrom(claim);
435	        if (!dueBy.isBefore(today)) {
436	            return figure;
437	        }
438	        long periods = ChronoUnit.DAYS.between(dueBy, today) / 30;
439	        RoundingMode rounding = rounding(claim);
440	        BigDecimal total = figure;
441	        for (long n = 1; n <= periods; n++) {
442	            BigDecimal pct = latePct(claim.sheetId(), dueBy.plusDays(30 * n));
443	            if (pct.signum() != 0) {
444	                total = total.add(total.multiply(pct).movePointLeft(2).setScale(2, rounding));
445	            }
446	        }
447	        return total;
448	    }
449	
450	    /** The claim's rate figure raised to the floor in force on the claim's date; null (no due) stays null, and a correction's due has no floor. */
451	    public BigDecimal floored(Claim claim, BigDecimal due) {
452	        return due == null || claim.isCorrection() ? due : due.max(floor(claim.sheetId(), claim.date()));
453	    }
454	
455	    /** The key an action's permitted roles are kept under: perm-<action>. */
456	    public static String permKey(String action) {
457	        return "perm-" + action;
458	    }
459	
460	    /** The roles an action is permitted to, as saved: a comma separated list, or "" for the standing rule. */
461	    public String perm(String sheetId, String action) {
462	        return get(sheetId, permKey(action));
463	    }
464	
465	    /** The standing rule: reassign and reopen by steward; open, settle, void, close and today by clerk and steward (anyone but a viewer). */
466	    private static List<String> standing(String action) {
467	        return action.equals("reassign") || action.equals("reopen") ? List.of(STEWARD) : ROLES;
468	    }
469	
470	    /** Whether the user's role may take the action on the sheet: as the permission matrix has it, else by the standing rule. */
471	    public boolean permits(String sheetId, String action, String user) {
472	        String saved = perm(sheetId, action);
473	        List<String> roles = saved.isEmpty() ? standing(action) : List.of(saved.split(","));
474	        String role = role(sheetId, user);
475	        // A restricted user may do what a clerk may: the role narrows only the people list they see.
476	        return roles.contains(RESTRICTED.equals(role) ? CLERK : role);
477	    }
478	
479	    /** The sheet's roles, by user name. */
480	    public List<Role> roles(String sheetId) {
481	        return jdbc.query("SELECT * FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? ORDER BY user_name",
482	                (rs, n) -> new Role(rs.getString("sheet_id"), rs.getString("user_name"), rs.getString("role")), sheetId);
483	    }
484	
485	    /** The role the user acts in: steward while the sheet's today is inside a delegation to them, else the role the sheet gave them. */
486	    public String role(String sheetId, String user) {
487	        return delegator(sheetId, user) != null ? STEWARD : givenRole(sheetId, user);
488	    }
489	
490	    /** The steward who delegated the steward role to the user for the sheet's today; null when none did. */
491	    public String delegator(String sheetId, String user) {
492	        return delegator(sheetId, user, sheets.today(sheetId));
493	    }
494	
495	    /** The steward who delegated the steward role to the user for {@code on}; null when none did. */
496	    public String delegator(String sheetId, String user, java.time.LocalDate on) {
497	        String name = user == null ? "" : user.trim();
498	        return name.isEmpty() ? null : delegations.delegator(sheetId, name, on);
499	    }
500	
501	    /** The role the sheet gave the user: clerk unless it gave them another (a delegation aside). */
502	    public String givenRole(String sheetId, String user) {
503	        List<String> roles = jdbc.queryForList("SELECT role FROM " + AsOf.table("sheet_role") + " WHERE sheet_id = ? AND user_name = ?",
504	                String.class, sheetId, user);
505	        return roles.isEmpty() ? CLERK : roles.get(0);
506	    }
507	
508	    /** Whether the user is a viewer on the sheet, and so may change nothing. */
509	    public boolean isViewer(String sheetId, String user) {
510	        return VIEWER.equals(role(sheetId, user == null ? "" : user.trim()));
511	    }
512	
513	    public void save(Role role) {
514	        jdbc.update("MERGE INTO sheet_role (sheet_id, user_name, role) KEY (sheet_id, user_name) VALUES (?, ?, ?)",
515	                role.sheetId(), role.user(), role.role());
516	    }
517	}
