package net.officefloor.hq.app.setting;

/** The sheet's settings as the screen sees them, each dated one as it is in force on the sheet's today: the clerk limit with two decimals, "" when there is none, the floor with two decimals, the terms in days, the late percent with two decimals, and the policy date as yyyy-MM-dd, "" when there is none (the sheet's today is), and the period numbering from-date as yyyy-MM-dd, "" when it is off, and the terms in force for each grade, in days (its own, or the sheet's terms when it has none), and the cap with two decimals, "" when there is none. {@code dated} is every value recorded for each dated setting, by setting key, by from-date. {@code perms} is the roles each action is permitted to, by action, as a comma separated list, "" for the standing rule. {@code graceDays} is the grace days, "" when they are off. {@code entryDate} is the entry date as yyyy-MM-dd, "" when it is off. {@code pot} is the pot with two decimals, "" when there is none. {@code parent} is the parent sheet's id, "" when there is none. {@code fiscalStartMonth} is the month (1 to 12) the fiscal year starts on. {@code alertThreshold} is the alert threshold with two decimals, "" when alerts are off. {@code escalateAfter} is the escalation gap in days, "" when it is off. {@code reviewSla} is the review SLA in days, "" when there is none. {@code proofKinds} are the proof kinds, comma separated, "" when there are none. {@code defaultGrade} is the default grade, "" when there is none (A is). {@code scoreMid} and {@code scoreHigh} are the score thresholds, "" when there is none. {@code scoreLog} is the score log switch, "on" or "" when it is off. {@code maxOpen} is the maximum of open claims per person, "" when there is none. {@code pendingSla} is the pending SLA in days, "" when there is none. */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        java.util.Map<String, String> gradeTerms, String cap, java.util.Map<String, java.util.List<Settings.DatedValue>> dated,
        java.util.Map<String, String> perms, String graceDays, String entryDate, String pot, String parent, String fiscalStartMonth, String alertThreshold, String escalateAfter, String reviewSla, String proofKinds, String defaultGrade, String scoreMid, String scoreHigh, String scoreLog, String maxOpen, String pendingSla) {
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class RespondWithSettings {
    public void respond(@PathVariable("sheetId") String sheetId, Settings settings, Sheets sheets,
            net.officefloor.hq.app.grade.Grades grades, ObjectResponse<SettingsResponse> response) {
        String sheet = sheetId.trim();
        List<String> sheetGrades = grades.all(sheet);
        LocalDate today = sheets.today(sheet);
        response.send(new SettingsResponse(settings.current(sheet, Settings.CLERK_LIMIT),
                settings.floor(sheet, today).setScale(2).toPlainString(), Integer.toString(settings.terms(sheet, today)),
                settings.latePct(sheet, today).setScale(2).toPlainString(), settings.get(sheet, Settings.POLICY_DATE),
                settings.get(sheet, Settings.PERIOD_NUMBERING_FROM), gradeTerms(settings, sheet, today, sheetGrades),
                settings.current(sheet, Settings.CAP), dated(settings, sheet, sheetGrades), perms(settings, sheet),
                settings.get(sheet, Settings.GRACE_DAYS), settings.get(sheet, Settings.ENTRY_DATE),
                settings.get(sheet, Settings.POT), settings.parent(sheet),
                Integer.toString(settings.fiscalStartMonth(sheet)), settings.get(sheet, Settings.ALERT_THRESHOLD),
                settings.get(sheet, Settings.ESCALATE_AFTER), settings.get(sheet, Settings.REVIEW_SLA),
                settings.get(sheet, Settings.PROOF_KINDS), settings.get(sheet, Settings.DEFAULT_GRADE),
                settings.get(sheet, Settings.SCORE_MID), settings.get(sheet, Settings.SCORE_HIGH),
                settings.get(sheet, Settings.SCORE_LOG), settings.get(sheet, Settings.MAX_OPEN),
                settings.get(sheet, Settings.PENDING_SLA)));
    }

    private static Map<String, String> gradeTerms(Settings settings, String sheet, LocalDate today, List<String> grades) {
        Map<String, String> terms = new LinkedHashMap<>();
        for (String grade : grades) {
            terms.put(grade, Integer.toString(settings.terms(sheet, grade, today)));
        }
        return terms;
    }

    private static Map<String, String> perms(Settings settings, String sheet) {
        Map<String, String> perms = new LinkedHashMap<>();
        for (String action : Settings.PERM_ACTIONS) {
            perms.put(action, settings.perm(sheet, action));
        }
        return perms;
    }

    private static Map<String, List<Settings.DatedValue>> dated(Settings settings, String sheet, List<String> grades) {
        Map<String, List<Settings.DatedValue>> dated = new LinkedHashMap<>();
        for (String key : Settings.dated(grades)) {
            dated.put(key, settings.history(sheet, key));
        }
        return dated;
    }
}
