/** The sheet's review SLA in days ("" for none, or until loaded). */
export function useReviewSla(sheetId: string): string {
  return useQuery(settingsQuery(sheetId)).data?.reviewSla ?? '';
}

/** The sheet's score thresholds, mid and high ("" for none, or until loaded). */
export function useScoreThresholds(sheetId: string): { mid: string; high: string } {
  const data = useQuery(settingsQuery(sheetId)).data;
  return { mid: data?.scoreMid ?? '', high: data?.scoreHigh ?? '' };
}

/** The sheet's cap in force on its today: what a person's due-total is at most ("" for none). */
export function useCap(sheetId: string): string {
  return useCurrent(sheetId, 'cap');
}

/** The sheet's late percents by from-date: what an overdue claim gains of its figure for every full 30 days it is overdue, as in force on each 30-day boundary date (the due-by plus 30, 60, 90 ... days). */
export function useLatePct(sheetId: string): DatedValue[] {
  return useQuery(settingsQuery(sheetId)).data?.dated?.['late-pct'] ?? [];
}

/** The sheet's policy date (yyyy-mm-dd): the one set, or the sheet's today when there is none. */
export function usePolicyDate(sheetId: string): string {
  const today = useSheetToday(sheetId);
  return useQuery(settingsQuery(sheetId)).data?.policyDate || today;
}

/** What a claim's late charge and its rounding depend on, as the sheet has it now. */
export function useLate(sheetId: string): Late {
  const dated = useQuery(settingsQuery(sheetId)).data?.dated;
  const grades = useGrades(sheetId);
  return {
    grace: Object.fromEntries(grades.map((g) => [g, dated?.[`grace-${g}`] ?? []])),
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    pct: useLatePct(sheetId),
    policy: usePolicyDate(sheetId),
    rounding: dated?.rounding ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
  };
}

/** The month (1 to 12) the sheet's fiscal year starts on. */
export function useFiscalStartMonth(sheetId: string): number {
  return Number(useQuery(settingsQuery(sheetId)).data?.fiscalStartMonth || '1');
}

/** The fiscal year a date (yyyy-mm-dd) falls in, named FY<yyyy> by the calendar year its first day falls in. */
export function fiscalYear(date: string, startMonth: number): string {
  const year = Number(date.slice(0, 4));
  const month = Number(date.slice(5, 7));
  return `FY${month >= startMonth ? year : year - 1}`;
}

export const rolesQuery = (sheetId: string) => ({
  queryKey: rolesKey(sheetId),
  queryFn: () => getJson<Role[]>(`/api/sheets/${encodeURIComponent(sheetId)}/roles`),
});
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/peopleQuery';
import { capLess, sumDue } from '../rates/ratesQuery';
import { useCap } from '../settings/settingsQuery';

/** A member of a pool: the person's id and name, their share percent with two decimals, whether they are retired, and their
 *  cut of the pool's pot with two decimals ("" when the pool is not balanced, there is no pot, every member is retired, or the member's dates do
 *  not include the sheet's today). A member that is
 *  another pool has its name as pool (null for a person) and personId 0; its cut is that pool's pot. periodCuts are its cut
 *  as it stood at the end of each period whose to-date is on or before the sheet's today ("" when it had none). */
export type PoolMember = {
  personId: number;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
  pool: string | null;
  periodCuts: { period: string; cut: string }[];
};

/** A pool of the sheet: its name, its members, its total share (a retired member's counting as given) with two decimals,
 *  and whether that total is exactly 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

/** Under the people's key, so re-loading the sheet, or any change to its people (a retirement), re-reads the pools. */
export const poolsKey = (sheetId: string) => [...peopleKey(sheetId), 'pools'] as const;

export const poolsQuery = (sheetId: string) => ({
  queryKey: poolsKey(sheetId),
  queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`),
});

/** A person's cut total: their cut in every pool they are a member of, added up; a pool that shows no cut adds nothing. */
export function cutTotal(pools: Pool[], personId: number): string {
  const cuts = pools.flatMap((p) => p.members.filter((m) => m.pool === null && m.personId === personId && m.cut !== '').map((m) => m.cut));
  return sumDue(cuts);
}

/** The cap a person's due-total is held to, by person id: the sheet's cap less their cut total, not below 0.00 ("" for no cap). */
export function useCapFor(sheetId: string): (personId: number) => string {
  const cap = useCap(sheetId);
  const pools = useQuery(poolsQuery(sheetId)).data ?? [];
  return (personId) => capLess(cap, cutTotal(pools, personId));
}
import { useQuery } from '@tanstack/react-query';
import { ClaimCells } from '../../slots/defs/claimColumns';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { claimsQuery } from '../claims/claimsQuery';
import type { Claim } from '../claims/claimsQuery';
import { gradeOn, peopleQuery } from '../people/peopleQuery';
import { useCapFor } from '../pools/poolsQuery';
import { patronSharesOf, patronsQuery } from '../patrons/patronsQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { useFloor, useLate } from '../settings/settingsQuery';
import { agedDue, excess, figure, personDue, personSum, ratesQuery, recentSettled, settledAndOpen, sumDue, sumOfShares, trimmedSum } from './ratesQuery';
import { ColumnShown } from '../people/useColumns';

function useSheetData(sheetId: string) {
  return {
    people: useQuery(peopleQuery(sheetId)).data ?? [],
    claims: useQuery(claimsQuery(sheetId)).data ?? [],
    rates: useQuery(ratesQuery(sheetId)).data ?? [],
    today: useSheetToday(sheetId),
    floor: useFloor(sheetId),
    late: useLate(sheetId),
    capFor: useCapFor(sheetId),
  };
}

function ClaimDue({ sheetId, claim }: { sheetId: string; claim: Claim }) {
  const { people, rates, floor, late } = useSheetData(sheetId);
  const person = people.find((p) => p.id === claim.personId);
  return <td data-testid="claim-due">{figure(claim, rates, person, floor, late)}</td>;
}

function PersonDueTotal({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late, capFor } = useSheetData(sheetId);
  return <td data-testid="person-due-total">{personDue(people.find((p) => p.id === personId), people, claims, rates, today, floor, late, capFor(personId))}</td>;
}

/** What a person's figures add up to above their cap (the sheet's cap less their cut total); 0.00 when they are not above it. */
function PersonExcess({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late, capFor } = useSheetData(sheetId);
  return <td data-testid="person-excess">{excess(personSum(people.find((p) => p.id === personId), people, claims, rates, today, floor, late), capFor(personId))}</td>;
}

/** A person's open claims' figures that count, split by the claim's age on the sheet's today: 0-30, 31-60 and 61+ days. */
function PersonAged({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  const [young, middle, old] = agedDue(people.find((p) => p.id === personId), people, claims, rates, today, floor, late);
  return (
    <>
      <td data-testid="person-aged-0-30">{young}</td>
      <td data-testid="person-aged-31-60">{middle}</td>
      <td data-testid="person-aged-61">{old}</td>
    </>
  );
}

/**
 * A person's backing: each patron's recent settled figure (see `recentSettled`) times their share (see `patronSharesOf`)
 * percent, added up and rounded half to even; 0.00 with no patrons.
 */
function PersonBacking({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, today } = useSheetData(sheetId);
  const shares = patronSharesOf(useQuery(patronsQuery(sheetId)).data ?? [], personId);
  const parts = shares
    .filter((s) => people.some((p) => p.id === s.patronId))
    .map((s): [string, string] => [recentSettled(s.patronId, claims, today), s.share]);
  return <td data-testid="person-backing">{sumOfShares(parts)}</td>;
}

/** A person's settled-total and open-total: their counting SETTLED, and OPEN and PENDING, claims' figures added up (not capped). */
function PersonSettledOpen({ sheetId, personId }: { sheetId: string; personId: number }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  const [settled, open] = settledAndOpen(people.find((p) => p.id === personId), people, claims, rates, today, floor, late);
  return (
    <>
      <td data-testid="person-settled-total">{settled}</td>
      <td data-testid="person-open-total">{open}</td>
    </>
  );
}

/** The sheet's settled-total and open-total: everyone's added up, each trimmed of the highest and lowest. */
function SettledOpenTotal({ sheetId }: { sheetId: string }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  const split = people.map((p) => settledAndOpen(p, people, claims, rates, today, floor, late));
  return (
    <p data-testid="rollup-settled-open">
      Settled <strong data-testid="rollup-settled-total">{trimmedSum(split.map(([s]) => s))}</strong>
      {' '}· Open <strong data-testid="rollup-open-total">{trimmedSum(split.map(([, o]) => o))}</strong>
    </p>
  );
}

/** The sheet's age buckets: everyone's open claims' figures by age (0-30, 31-60, 61+ days) added up (not trimmed). */
function AgedTotal({ sheetId }: { sheetId: string }) {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  const aged = people.map((p) => agedDue(p, people, claims, rates, today, floor, late));
  return (
    <p data-testid="rollup-aged">
      0–30 <strong data-testid="rollup-aged-0-30">{sumDue(aged.map(([y]) => y))}</strong>
      {' '}· 31–60 <strong data-testid="rollup-aged-31-60">{sumDue(aged.map(([, m]) => m))}</strong>
      {' '}· 61+ <strong data-testid="rollup-aged-61">{sumDue(aged.map(([, , o]) => o))}</strong>
    </p>
  );
}

/** The sheet's due-total: every person's due-total added up, skipping n/a, trimmed of the highest and lowest. */
export function useSheetDueTotal(sheetId: string) {
  const { people, claims, rates, today, floor, late, capFor } = useSheetData(sheetId);
  return trimmedSum(people.map((p) => personDue(p, people, claims, rates, today, floor, late, capFor(p.id))));
}

/**
 * Per grade (as `grades` orders them), the due-totals of the people on it today, retired people left out, added up
 * skipping n/a — as the summary shows them.
 */
export function useGradeDueTotals(sheetId: string, grades: string[]): string[] {
  const { people, claims, rates, today, floor, late, capFor } = useSheetData(sheetId);
  const unretired = people.filter((p) => p.retiredFrom === null);
  return grades.map((g) =>
    sumDue(unretired.filter((p) => gradeOn(p, today) === g).map((p) => personDue(p, people, claims, rates, today, floor, late, capFor(p.id)))),
  );
}

/** One person's due-total, as in their row; null when there is no such person. */
export function usePersonDueTotal(sheetId: string, personId: number | undefined) {
  const { people, claims, rates, today, floor, late, capFor } = useSheetData(sheetId);
  const person = people.find((p) => p.id === personId);
  return person ? personDue(person, people, claims, rates, today, floor, late, capFor(person.id)) : null;
}

/** Every person's settled-total and open-total, as in their row, in sheet order. */
export function usePeopleSettledOpen(sheetId: string): [string, string][] {
  const { people, claims, rates, today, floor, late } = useSheetData(sheetId);
  return people.map((p) => settledAndOpen(p, people, claims, rates, today, floor, late));
}

/** Every person's due-total, as in their row, by person id. */
export function usePeopleDueTotals(sheetId: string): Map<number, string> {
  const { people, claims, rates, today, floor, late, capFor } = useSheetData(sheetId);
  return new Map(people.map((p) => [p.id, personDue(p, people, claims, rates, today, floor, late, capFor(p.id))]));
}

function DueTotal({ sheetId }: { sheetId: string }) {
  return (
    <p data-testid="rollup-due">
      Due total <strong data-testid="rollup-due-total">{useSheetDueTotal(sheetId)}</strong>
    </p>
  );
}

export const contributions = [
  ClaimCells.fill({ order: 10, Component: ClaimDue }),
  PersonHeaders.fill({ order: 15, Component: () => <ColumnShown column="due-total"><th>Due</th></ColumnShown> }),
  PersonCells.fill({ order: 15, Component: (ctx) => <ColumnShown column="due-total"><PersonDueTotal {...ctx} /></ColumnShown> }),
  PersonHeaders.fill({ order: 15.2, Component: () => <><th>Settled</th><th>Open</th></> }),
  PersonCells.fill({ order: 15.2, Component: PersonSettledOpen }),
  PersonHeaders.fill({ order: 15.5, Component: () => <><th>0–30</th><th>31–60</th><th>61+</th></> }),
  PersonCells.fill({ order: 15.5, Component: PersonAged }),
  PersonHeaders.fill({ order: 16, Component: () => <ColumnShown column="excess"><th>Excess</th></ColumnShown> }),
  PersonCells.fill({ order: 16, Component: (ctx) => <ColumnShown column="excess"><PersonExcess {...ctx} /></ColumnShown> }),
  PersonHeaders.fill({ order: 22, Component: () => <ColumnShown column="backing"><th>Backing</th></ColumnShown> }),
  PersonCells.fill({ order: 22, Component: (ctx) => <ColumnShown column="backing"><PersonBacking {...ctx} /></ColumnShown> }),
  SheetPanel.fill({ order: 25, Component: DueTotal }),
  SheetPanel.fill({ order: 25.5, Component: SettledOpenTotal }),
  SheetPanel.fill({ order: 25.55, Component: AgedTotal }),
];
